  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'Οι δημιουργοί πρέπει να παρέχουν ακριβείς τίτλους, περιγραφές, κατηγορίες, γλώσσες, μικρογραφίες, υπότιτλους, ορατότητα και ρυθμίσεις προγραμματισμού. Τα προγραμματισμένα βίντεο δεν είναι δημόσια μέχρι την προγραμματισμένη ώρα και την επιτυχή επεξεργασία τους.',
