  'Optional, but recommended' => 'Προαιρετικό, αλλά συνιστάται',
  'Other' => 'Άλλο',
  'Partnerships, press, and platform operations.' => 'Συνεργασίες, τύποι και λειτουργίες πλατφόρμας.',
  'Payment help' => 'Βοήθεια πληρωμής',
  'Platform' => 'Πλατφόρμα',
  'Playback' => 'Αναπαραγωγή',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Η πρόοδος αναπαραγωγής, η κατάσταση παρακολούθησης αργότερα, οι επισημάνσεις "μου αρέσει", τα σχόλια, οι συνδρομές, οι ειδοποιήσεις και τα αναλυτικά στοιχεία διαχειριστή αποθηκεύονται στη βάση δεδομένων όταν συνδέονται με λειτουργίες της πλατφόρμας που έχουν πιστοποιηθεί.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Η αναπαραγωγή, τα σχόλια, τα "μου αρέσει", η παρακολούθηση αργότερα, οι συνδρομές, οι ειδοποιήσεις, τα μηνύματα, οι λίστες αναπαραγωγής και οι ρυθμίσεις γλώσσας είναι διαθέσιμα μέσω του κύριου μενού πλοήγησης και του λογαριασμού.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'Το PlayHub είναι μια πλατφόρμα βίντεο για τη μεταφόρτωση, την παρακολούθηση, τον προγραμματισμό, τη διαχείριση και την εποπτεία περιεχομένου δημιουργού από έναν λογαριασμό.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'Το PlayHub είναι η πλατφόρμα βίντεο που εκτελείται σε αυτήν την ανάπτυξη, κατασκευασμένη για δημιουργούς, θεατές, κοινότητες και χειριστές πλατφόρμας.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'Το PlayHub παρέχει κανάλια δημιουργών, μεταφορτώσεις βίντεο, προγραμματισμένες δημοσιεύσεις, συνδρομές, σχόλια, λίστες αναπαραγωγής, παρακολούθηση αργότερα, σελίδες ζωντανού περιεχομένου και εργαλεία διαχείρισης από μία πλατφόρμα.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'Το PlayHub χρησιμοποιεί απαραίτητα cookie και χώρο αποθήκευσης προγράμματος περιήγησης για περιόδους σύνδεσης, έλεγχο ταυτότητας API, συμπεριφορά CSRF/ασφάλειας, επιλογή γλώσσας, επιλογή θέματος, κατάσταση μενού λογαριασμού και άλλες λειτουργίες που απαιτούνται για τη λειτουργία της εφαρμογής.',
  'playhub_language, theme' => 'playhub_language, θέμα',
  'Popular questions' => 'Δημοφιλείς ερωτήσεις',
  'Preference storage' => 'Προτιμώμενος χώρος αποθήκευσης',
  'Privacy Policy' => 'Πολιτική Απορρήτου',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'Το απόρρητο, τα cookie, η ασφάλεια του λογαριασμού, τα μηνύματα υποστήριξης και τα δεδομένα εποπτείας διαχειρίζονται μέσω των πολιτικών και των αρχείων υποστήριξης που είναι συνδεδεμένα στο PlayHub.',
  'Profile, login, security, and settings help.' => 'Βοήθεια για το προφίλ, τη σύνδεση, την ασφάλεια και τις ρυθμίσεις.',
  'Profile, security, and preferences.' => 'Προφίλ, ασφάλεια και προτιμήσεις.',
  'Public API route' => 'Δημόσια διαδρομή API',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'Τα δημόσια τελικά σημεία JSON περιλαμβάνουν /api/health για την κατάσταση ανάπτυξης και /api/upload-options για κατηγορίες μεταφόρτωσης, γλώσσες, όρια, μέγεθος κομματιού και τάσεις ετικέτες.',
  'Public REST API' => 'Public REST API',
  'Published videos' => 'Δημοσιευμένα βίντεο',
