  'Platform capabilities' => 'Πραγματικές δυνατότητες πλατφόρμας',
  'Platform overview' => 'Πραγματικά δεδομένα πλατφόρμας',
  'Reason' => 'Λόγος',
  'Recent creator channels' => 'Πρόσφατα κανάλια δημιουργών',
  'Refund' => 'Επιστροφή χρημάτων',
  'Refund and paid feature guidance.' => 'Οδηγίες για επιστροφή χρημάτων και επί πληρωμή.',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'Ο χειρισμός επιστροφής χρημάτων για λειτουργίες του PlayHub επί πληρωμή εξαρτάται από τα πραγματικά αρχεία χρέωσης που συνδέονται με αυτήν την ανάπτυξη.',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'Ο χειρισμός της επιστροφής χρημάτων συνδέεται με τα πραγματικά αρχεία χρέωσης και τον έλεγχο του διαχειριστή. Εάν η χρέωση δεν έχει διαμορφωθεί για αυτήν την ανάπτυξη, δεν υπάρχει χρέωση πλατφόρμας για επιστροφή χρημάτων.',
  'Refund issued' => 'Εκδόθηκε η επιστροφή χρημάτων',
