  'Registered users' => 'Εγγεγραμμένοι χρήστες',
  'Related legal pages' => 'Σχετικές νομικές σελίδες',
  'Report a problem' => 'Αναφέρετε ένα πρόβλημα',
  'Reports, moderation, and privacy.' => 'Αναφορές, εποπτεία και απόρρητο.',
  'Reports, moderation, privacy, and community safety.' => 'Αναφορές, εποπτεία, απόρρητο και ασφάλεια της κοινότητας.',
  'Request a refund' => 'Ζητήστε επιστροφή χρημάτων',
  'Required' => 'Απαιτείται',
  'Required for login, security, and app routing.' => 'Απαιτείται για σύνδεση, ασφάλεια και δρομολόγηση εφαρμογών.',
  'Response targets' => 'Στόχοι απόκρισης',
  'Retention and access' => 'Διατήρηση και πρόσβαση',
  'Review privacy and cookie details for this deployment.' => 'Ελέγξτε τις λεπτομέρειες απορρήτου και cookie για αυτήν την ανάπτυξη.',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'Κανόνες για τη χρήση αυτής της ανάπτυξης του PlayHub ως θεατής, δημιουργός ή διαχειριστής.',
  'Safety' => 'Ασφάλεια',
  'Safety / technical' => 'Ασφάλεια / τεχνική',
  'Safety and content reports' => 'Αναφορές ασφάλειας και περιεχομένου',
  'Safety or report' => 'Ασφάλεια ή αναφορά',
  'Sample endpoints' => 'Δείγματα τελικών σημείων',
  'sample endpoints loaded' => 'φορτώθηκαν δείγματα τελικών σημείων',
  'Schedule video' => 'Προγραμματίστε το βίντεο',
  'Scheduled video release and reminders.' => 'Προγραμματισμένη κυκλοφορία βίντεο και υπενθυμίσεις.',
  'Scheduled videos' => 'Προγραμματισμένα βίντεο',
  'Scheduling a video release' => 'Προγραμματισμός κυκλοφορίας βίντεο',
  'Search for answers...' => 'Αναζήτηση απαντήσεων...',
  'Search help articles, topics, or questions...' => 'Αναζήτηση άρθρων βοήθειας, θεμάτων ή ερωτήσεων...',
  'Select a reason' => 'Διάλεξε λόγο',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Διάλεξε ένα ή περισσότερα αρχεία βίντεο και συμπλήρωσε τα απαραίτητα στοιχεία. Όρισε κατηγορία, γλώσσα, μικρογραφία και ορατότητα, μετά δημοσίευσέ τα. Τα μεγάλα αρχεία ανεβαίνουν σε τμήματα πριν ξεκινήσει η επεξεργασία.',
  'Send a message and it will be saved for admins.' => 'Στείλτε ένα μήνυμα και θα αποθηκευτεί για τους διαχειριστές.',
  'Send billing details to admin support for review.' => 'Στείλτε τα στοιχεία χρέωσης στην υποστήριξη διαχειριστή για έλεγχο.',
  'Send message' => 'Αποστολή μηνύματος',
  'Send order details through the refund popup.' => 'Στείλτε τα στοιχεία παραγγελίας μέσω του αναδυόμενου παραθύρου επιστροφής χρημάτων.',
  'Send us a message' => 'Στείλτε μας ένα μήνυμα',
  'Sending...' => 'Αποστολή...',
  'Server configured' => 'Ο διακομιστής διαμορφώθηκε',
  'server records' => 'εγγραφές διακομιστή',
  'Service operation' => 'Λειτουργία σέρβις',
  'session, token' => 'συνεδρία, διακριτικό',
  'Settings and login' => 'Ρυθμίσεις και σύνδεση',
  'Short summary' => 'Σύντομη περίληψη',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Συνδεθείτε και χρησιμοποιήστε τις Ρυθμίσεις για λογαριασμό, προφίλ, κωδικό πρόσβασης, ειδοποίηση, απόρρητο και προτιμήσεις δημιουργού. Τα προβλήματα μεταφόρτωσης δημιουργού και περιεχομένου θα πρέπει να περιλαμβάνουν τον τίτλο του βίντεο, το κανάλι, το πρόγραμμα περιήγησης και οποιοδήποτε σφάλμα επεξεργασίας που εμφανίζεται στη σελίδα μεταφόρτωσης.',
  'Sign in for account support' => 'Συνδεθείτε για υποστήριξη λογαριασμού',
  'Signed in' => 'Συνδεδεμένος',
  'Start uploading' => 'Ξεκινήστε τη μεταφόρτωση',
  'Still can’t find an answer?' => 'Ακόμα δεν μπορείτε να βρείτε απάντηση;',
  'Stored for admins' => 'Αποθηκευμένο για διαχειριστές',
  'Stores language, theme, and interface preferences.' => 'Αποθηκεύει τις προτιμήσεις γλώσσας, θέματος και διεπαφής.',
  'Studio, playlists, analytics, channels.' => 'Στούντιο, λίστες αναπαραγωγής, αναλυτικά στοιχεία, κανάλια.',
  'Submit a billing or refund message to admin support.' => 'Υποβάλετε ένα μήνυμα χρέωσης ή επιστροφής χρημάτων στην υποστήριξη διαχειριστή.',
  'Submit refund request' => 'Υποβολή αιτήματος επιστροφής χρημάτων',
  'Submit request' => 'Υποβολή αιτήματος',
  'Subscription cancellation' => 'Ακύρωση συνδρομής',
  'Support dashboard' => 'Υποστήριξη ταμπλό',
  'System status' => 'Κατάσταση συστήματος',
  'Table' => 'Πίνακας',
  'Taxonomies' => 'Ταξινομίες',
  'Technical issue' => 'Τεχνικό θέμα',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Τεχνικές σημειώσεις για ενσωματώσεις με το τρέχον API PlayHub και ροή εργασιών μεταφόρτωσης.',
  'Tell us more about your question or request...' => 'Πείτε μας περισσότερα για την ερώτηση ή το αίτημά σας...',
  'Terms of Use' => 'Όροι Χρήσης',
  'The configured' => 'Το διαμορφωμένο',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Η σελίδα προγραμματιστή συνδέεται με το ζωντανό backend της Laravel: το απόθεμα διαδρομής, οι μετρήσεις βάσεων δεδομένων, τα όρια μεταφόρτωσης και τα μεταδεδομένα πλατφόρμας φορτώνονται από το /api/developers.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Η διεπαφή αποθηκεύει προτιμήσεις όπως η επιλεγμένη γλώσσα, το θέμα, η ουρά αναπαραγωγής, η πρόοδος παρακολούθησης και η κατάσταση διεπαφής, ώστε η εμπειρία να παραμένει συνεπής κατά την πλοήγηση και τις επαναφορτώσεις σελίδων.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Η εργασία επεξεργασίας κωδικοποιεί παραδόσεις, δημιουργεί μικρογραφίες όταν χρειάζεται, αποθηκεύει υπότιτλους και επισημαίνει τα βίντεο έτοιμα όταν ολοκληρωθεί η επεξεργασία. Τα μελλοντικά προγραμματισμένα βίντεο παραμένουν ιδιωτικά μέχρι να τα δημοσιεύσει ο προγραμματιστής.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Το σύστημα μεταφόρτωσης υποστηρίζεται από βάση δεδομένων, υποστηρίζει κατηγορίες και γλώσσες από το API, επεξεργάζεται τα μεταφορτωμένα βίντεο, αποθηκεύει μικρογραφίες και υπότιτλους και διατηρεί το προγραμματισμένο περιεχόμενο ιδιωτικό μέχρι την ώρα κυκλοφορίας του.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Αυτή η σελίδα εξηγεί πώς το PlayHub χρησιμοποιεί cookies και χώρο αποθήκευσης προγράμματος περιήγησης για περιόδους σύνδεσης, ασφάλεια, προτιμήσεις, αναπαραγωγή και λειτουργίες ελέγχου ταυτότητας.',
  'Ticket source' => 'Πηγή εισιτηρίου',
  'Top content categories' => 'Κορυφαίες κατηγορίες περιεχομένου',
  'Topic' => 'Θέμα',
  'Transaction / invoice' => 'Συναλλαγή / τιμολόγιο',
  'Transaction / invoice ID' => 'Αναγνωριστικό συναλλαγής / τιμολογίου',
  'Unable to send message.' => 'Δεν είναι δυνατή η αποστολή μηνύματος.',
  'Unable to submit refund request.' => 'Δεν είναι δυνατή η υποβολή αιτήματος επιστροφής χρημάτων.',
  'Understanding admin support tickets' => 'Κατανόηση των εισιτηρίων υποστήριξης διαχειριστή',
  'Upload and processing help' => 'Βοήθεια μεταφόρτωσης και επεξεργασίας',
  'Upload chunks' => 'Ανεβάστε κομμάτια',
  'Upload issues' => 'Ζητήματα μεταφόρτωσης',
  'Upload languages' => 'Μεταφόρτωση γλωσσών',
  'Upload limit' => 'Όριο μεταφόρτωσης',
  'Upload options' => 'Επιλογές μεταφόρτωσης',
  'Upload or processing' => 'Μεταφόρτωση ή επεξεργασία',
  'Upload page' => 'Μεταφόρτωση σελίδας',
  'Upload pipeline' => 'Μεταφόρτωση αγωγού',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Ανεβάστε, παρακολουθήστε, εγγραφείτε, εποπτεύστε και δημιουργήστε με ζωντανά δεδομένα του PlayHub.',
  'Uploaded videos' => 'Μεταφορτωμένα βίντεο',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Τα μεταφορτωμένα βίντεο κωδικοποιούνται σε παραστάσεις με δυνατότητα αναπαραγωγής. Ο χρόνος επεξεργασίας εξαρτάται από το μέγεθος του αρχείου, τη διάρκεια, το φόρτο του διακομιστή και την κατάσταση της ουράς. Η σελίδα μεταφόρτωσης και το Creator Studio εμφανίζουν πραγματική κατάσταση επεξεργασίας από την εγγραφή βίντεο.',
  'Uploads, scheduling, and processing are available.' => 'Διατίθενται μεταφορτώσεις, προγραμματισμός και επεξεργασία.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Χρησιμοποιήστε το /api/βίντεο, τα τελικά σημεία καναλιών και τις πιστοποιημένες διαδρομές για τις ροές εργασίας του δημιουργού.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Χρησιμοποιήστε ενσωματωμένες ενέργειες αναφοράς για βίντεο και σχόλια, ώστε οι διαχειριστές να λαμβάνουν την ακριβή αναφορά περιεχομένου. Οι σελίδες του πίνακα ελέγχου διαχειριστή χρησιμοποιούν ζωντανά δεδομένα βάσης δεδομένων για χρήστες, περιεχόμενο, αναφορές, δημιουργία εσόδων, αναλυτικά στοιχεία, υποστήριξη, ρόλους και ρυθμίσεις συστήματος.',
  'Use Contact Us' => 'Χρήση Επικοινωνήστε μαζί μας',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Χρησιμοποιήστε JSON για κανονικά αιτήματα API και FormData για μεταφορτώσεις αρχείων. Μην παρακάμπτετε την επικύρωση: οι κατηγορίες και οι γλώσσες είναι αναγνωριστικά βάσεων δεδομένων, η ορατότητα περιορίζεται σε δημόσια, μη καταχωρισμένα ή ιδιωτικά και οι υπότιτλοι δέχονται αρχεία SRT, VTT ή TXT.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Χρησιμοποιήστε τις Ρυθμίσεις για να ενημερώσετε το προφίλ, την ασφάλεια, τον κωδικό πρόσβασης, την παράδοση δύο παραγόντων, τις συσκευές, τις προτιμήσεις και τις επιλογές ειδοποιήσεων. Εάν δεν μπορείτε να αποκτήσετε πρόσβαση στον λογαριασμό σας, χρησιμοποιήστε τη ροή σύνδεσης και δώστε το email του λογαριασμού στον διαχειριστή του ιστότοπου.',
  'Use the contact form' => 'Χρησιμοποιήστε τη φόρμα επικοινωνίας',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Χρησιμοποιήστε τις ενέργειες αναφοράς σε βίντεο, σχόλια και αναρτήσεις κοινότητας, ώστε οι διαχειριστές να λαμβάνουν την ακριβή αναφορά περιεχομένου.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Χρησιμοποιήστε τις ενέργειες αναφοράς σε βίντεο, σχόλια και αναρτήσεις κοινότητας όταν το περιεχόμενο μπορεί να παραβιάζει τους κανόνες της πλατφόρμας. Αυτές οι αναφορές συνδέονται με το πραγματικό αρχείο περιεχομένου και είναι καλύτερες από ένα γενικό μήνυμα, επειδή οι διαχειριστές μπορούν να ελέγξουν το ακριβές στοιχείο.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Χρησιμοποιήστε το σωστό κανάλι PlayHub για βοήθεια λογαριασμού, αναφορές περιεχομένου, τεχνικά ζητήματα και αιτήματα διαχειριστή.',
  'Video categories' => 'Κατηγορίες βίντεο',
  'Video for everyone. Built for creators and viewers.' => 'Βίντεο για όλους. Κατασκευασμένο από πραγματικά δεδομένα πλατφόρμας.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Ζητήματα μεταφόρτωσης, προγραμματισμού, μικρογραφιών και επεξεργασίας βίντεο.',
  'Videos, thumbnails, captions, processing.' => 'Βίντεο, μικρογραφίες, λεζάντες, επεξεργασία.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Οι θεατές μπορούν να περιηγηθούν σε κατηγορίες, να αναζητήσουν βίντεο, να παρακολουθήσουν περιεχόμενο, να εγγραφούν σε κανάλια, να αποθηκεύσουν βίντεο για να παρακολουθήσουν αργότερα, να σχολιάσουν, να λαμβάνουν ειδοποιήσεις και να διαχειριστούν τις προτιμήσεις γλώσσας και προσβασιμότητας.',
  'Viewing and community help' => 'Προβολή και βοήθεια κοινότητας',
  'Waiting for backend endpoint inventory.' => 'Αναμονή για το απόθεμα τελικού σημείου υποστήριξης.',
  'We’re here to help.' => 'Είμαστε εδώ για να βοηθήσουμε.',
  'What is PlayHub?' => 'Τι είναι το PlayHub;',
  'What PlayHub does' => 'Τι κάνει το PlayHub',
  'Where do contact messages go?' => 'Πού πηγαίνουν τα μηνύματα επικοινωνίας;',
  'Why is my video still processing?' => 'Γιατί το βίντεό μου εξακολουθεί να υποβάλλεται σε επεξεργασία;',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Ναί. Χρησιμοποιήστε το εγγενές πεδίο ημερομηνίας και ώρας χρονοδιαγράμματος στη σελίδα μεταφόρτωσης. Το backend αποθηκεύει το scheduled_at, επεξεργάζεται το βίντεο, το διατηρεί ιδιωτικό όσο η ημερομηνία είναι στο μέλλον και το απελευθερώνει όταν ο προγραμματιστής Laravel εκτελείται μετά την προγραμματισμένη ώρα.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Ναί. Χρησιμοποιήστε το εγγενές πεδίο χρονοδιαγράμματος στη Μεταφόρτωση. Το backend αποθηκεύει το scheduled_at και δημοσιεύει το βίντεο μετά την επεξεργασία όταν φτάσει η ώρα προγραμματισμού.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Περιηγείστε ως επισκέπτης. Συνδεθείτε για να αποκτήσετε πρόσβαση σε εργαλεία για συγκεκριμένο λογαριασμό.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Είστε υπεύθυνοι για τα διαπιστευτήρια του λογαριασμού σας, τη δραστηριότητα του προφίλ, το μεταφορτωμένο περιεχόμενο, τα σχόλια, τα μηνύματα και τυχόν ενέργειες δημιουργού ή διαχειριστή που εκτελούνται από τον λογαριασμό σας. Χρησιμοποιήστε ισχυρούς κωδικούς πρόσβασης και διατηρήστε ενημερωμένες τις μεθόδους παράδοσης δύο παραγόντων.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Μπορείτε να διαγράψετε τα cookie του προγράμματος περιήγησης και τον τοπικό χώρο αποθήκευσης στις ρυθμίσεις του προγράμματος περιήγησής σας. Η εκκαθάριση του βασικού χώρου αποθήκευσης ενδέχεται να αποσυνδεθεί, να επαναφέρει τις προτιμήσεις γλώσσας/θέματος, να καταργήσει την τοπική κατάσταση αναπαραγωγής και να απαιτήσει να συνδεθείτε ξανά.',
  'You receive a response by email.' => 'Λαμβάνετε απάντηση μέσω email.',
  'You’re in control' => 'Εσύ επιλέγεις',
  'Your choices' => 'Οι επιλογές σου',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Το μήνυμά σας αποθηκεύεται απευθείας στο backend του ιστότοπου και εμφανίζεται στον πίνακα ελέγχου διαχειριστή στην ενότητα Υποστήριξη.',
